def test_report_failure_sends_edited_file_not_original(tmp_path, monkeypatch):
    """'Edit it before sending' must be true: the email/issue body is read back
    from the (possibly edited) file, not the original generated text."""
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    edited = tmp_path / "bug-reports" / "edited.md"

    def fake_save(text, when=None):
        edited.parent.mkdir(parents=True, exist_ok=True)
        edited.write_text("EDITED REPORT BODY", encoding="utf-8")
        return edited
    monkeypatch.setattr(bugreport, "save_report", fake_save)

    opened = []
    bugreport.report_failure(
        summary="bug", interactive=True,
        open_browser=lambda u: opened.append(u), prompt=lambda _t: "2")  # [2] = email
    assert opened
    assert "EDITED REPORT BODY" in unquote(opened[0])   # the edit, not the original


